local KTool = CS.Engine.Lib.KTool
---@class StoreChargeRewardNode
local StoreChargeRewardNode = Class('StoreChargeRewardNode')
function StoreChargeRewardNode:__init()
    self.callBack = nil
    self.index = nil
    self.delegate = nil
    self.data = nil
end

function StoreChargeRewardNode:__delete()
    self.callBack = nil
    self.index = nil
    self.delegate = nil
    self.data = nil
end

function StoreChargeRewardNode:SetCallBackAndIndex(callBack,index,delegate)
    self.callBack = callBack
    self.index = index
    self.delegate = delegate
end

function StoreChargeRewardNode:Awake()
    SetButtonAction(self.BtnNode,Bind(self,self.OnBtnNodeClick))
    self:InitRewardEnv()
end

function StoreChargeRewardNode:InitRewardEnv()
    if self.RewardNode then
        local env = CfUtils.GetLuaScr(self.RewardNode,"Game.Behaviours.CommonGoodsListLight")
        if env then
           self.rewardNodeEnv = env
        end
    end
end

function StoreChargeRewardNode:OnBtnNodeClick()
    if self.callBack then
        self.callBack(self.data)
    end
end

function StoreChargeRewardNode:RefreshShow(data)
    if isNull(data) then return end
    self.data = data
    CfUtils.FillText(self.TextPeriod,localize("_num_阶",{ _num_ = self.index }))
    CfUtils.FillText(self.GoodNum,self.data.amount)

    local goodsId = self.delegate.data.costType
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if goodsVo then
        CfUtils.FillImage(self.ImgGoodIcon,goodsVo.photoPath)
    end
    KTool.SetActive(self.ImgMask.gameObject,false)
    KTool.SetActive(self.UIFX_Available.gameObject,false)
    local point = self.delegate.curPoint
    if point >= self.data.amount then
        CfUtils.SetUISwitchText(self.GoodNum,2)
        local isGet = self.delegate:IsGetById(self.data.id)
        KTool.SetActive(self.TextRemind.gameObject,not isGet)
        if isGet then
            KTool.SetActive(self.ImgMask.gameObject,true)
        else
            KTool.SetActive(self.UIFX_Available.gameObject,true)
            CfUtils.SetUISwitchText(self.TextRemind,2)
        end
    else
        KTool.SetActive(self.TextRemind.gameObject,true)
        CfUtils.SetUISwitchText(self.TextRemind,1)
        CfUtils.SetUISwitchText(self.GoodNum,1)
    end
    self:RefreshRewardShow()
end

function StoreChargeRewardNode:RefreshRewardShow()
    if not isNull(self.rewardNodeEnv) then
        self.rewardNodeEnv:FreshBaseUI(self.data.rewards)
    end
end

function StoreChargeRewardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return StoreChargeRewardNode